import itertools, json
jobs='ABCDE'
slot={'A':[0,1,4,11,3], 'B':[2,3,3,2,5], 'C':[4,8,2,10,8], 'D':[3,2,11,3,4], 'E':[10,6,10,10,4]}
transfer=dict(zip(jobs,[[0,3,3,0,5],[5,0,4,2,0],[2,2,0,2,5],[0,5,5,0,5],[1,4,3,1,0]]))
def nominal(p):
 return sum(slot[j][i] for i,j in enumerate(p))+sum(transfer[a][jobs.index(b)] for a,b in zip(p,p[1:]))
def legal(p,s):
 if p.index('A')>p.index('D'): return False
 if s=='rain': return p[0] not in 'DA'
 if s=='road': return p[3]!='C' and p[1]!='E'
 return p[0] not in 'AB'
def penalty(p,s):
 if s=='rain': return 6*p.index('C')
 if s=='road': return 6*max(0,p.index('D')-2)
 return 10*max(0,p.index('E')-1)
results=[]
for p in itertools.permutations(jobs):
 if p.index('A')>p.index('D'): continue
 neighbors=[(p,0)]
 for i,j in itertools.combinations(range(5),2):
  q=list(p); q[i],q[j]=q[j],q[i]; neighbors.append((tuple(q),1))
 repairs={}; costs={}
 for s in ['rain','road','lift']:
  opts=[(nominal(q)+penalty(q,s)+ex,''.join(q)) for q,ex in neighbors if legal(q,s)]
  if not opts: break
  costs[s],repairs[s]=min(opts)
 if len(costs)==3:
  results.append({'roster':''.join(p),'score':nominal(p)+max(costs.values()),'repairs':repairs,'repair_costs':costs})
results.sort(key=lambda x:(x['score'],x['roster']))
answer=results[0].copy()
answer['feasible_count']=len(results)
answer['next_score']=min(r['score'] for r in results if r['score']>answer['score'])
print(json.dumps(answer))
print('best candidates',results[:3])

